#!/usr/bin/env python3
from pathlib import Path
import sys
import re
root=Path(__file__).resolve().parents[1]
java=root/'android/app/src/main/java/com/braseiro/pathfinder2e'
main=(java/'MainActivity.java').read_text('utf-8')
controller=(java/'AudioController.java').read_text('utf-8')
smart=(java/'SmartAudioLibrary.java').read_text('utf-8')
db=(java/'AudioCatalogDb.java').read_text('utf-8')
worker=(java/'AudioLibraryImportWorker.java').read_text('utf-8')
soundpool=(java/'SfxSoundPoolBackend.java').read_text('utf-8')
cache=(java/'TtsCache.java').read_text('utf-8')
narrative=(java/'NarrativeAudioEngine.java').read_text('utf-8')
naturalizer=(java/'NarrativeLocationNaturalizer.java').read_text('utf-8')
diagnostics=(java/'AudioDiagnosticsRepository.java').read_text('utf-8')
session=(java/'AudioSessionCoordinator.java').read_text('utf-8')
gradle=(root/'android/app/build.gradle.kts').read_text('utf-8')
version_props=dict(line.strip().split('=',1) for line in (root/'version.properties').read_text('utf-8').splitlines() if '=' in line)
version_name=version_props['VERSION_NAME'];version_code=version_props['VERSION_CODE']
manifest=(root/'android/app/src/main/AndroidManifest.xml').read_text('utf-8')
checks=[]
def check(name, cond): checks.append((name,bool(cond)))
check('versão central '+version_name, 'versionName = appVersionName' in gradle and 'versionCode = appVersionCode' in gradle)
check('catálogo V3 separado', 'audio_catalog_v3.db' in db and 'audio_sessions' in db and 'audio_import_jobs' in db)
check('reimportação limpa autorizada', 'catalogDb.clearAll()' in smart and 'audio_library_v3' in worker)
check('campanha não apagada na migração', 'deleteDatabase("braseiro' not in main and 'audio_catalog_v2.db' in main)
check('coordenador único de PLAY', 'AudioSessionCoordinator' in main and 'beginCoordinatedAudioSession' in main and 'failCoordinatedAudioSession' in main)
check('sessões canceláveis', 'runId' in session and 'sessionId' in session and 'superseded' in session and 'cancel(' in session)
check('SoundPool 12 streams', 'SoundPool.Builder' in soundpool and 'setMaxStreams(12)' in soundpool)
check('fallback MediaPlayer', 'playSfxMediaPlayer' in controller and 'native-play-rejected' in controller)
check('SFX pré-carregado fora da UI', 'preloadSfx' in controller and 'audio.preloadSfx' in narrative and 'cuePlanner.execute' in narrative)
check('SFX nunca em loop', 'setLooping(false)' in controller and 'MAX_ONE_SHOT_MS' in controller)
check('SFX cancela sessão anterior', 'cancelSession' in soundpool and 'beginPlaybackSession' in controller)
check('SFX desativa após 3 falhas', 'failure_count+1>=3' in db)
check('primeiro Charon em paralelo', 'prepareSceneAsync' in main and 'synthesizeChunk(chunks,0,session,coordinated)' in main and 'if(ready!=null)handler.post(ready)' in narrative)
check('Charon pré-busca próximo bloco', 'synthesizeChunk(chunks,index+1,session,coordinated)' in main)
policy=(java/'NarrationPlaybackPolicy.java').read_text('utf-8')
chunker=(java/'NarrationChunker.java').read_text('utf-8')
check('fallback Charon Android', 'fallbackToNativeNarration' in main and 'CHARON_WAIT_STATUS_MS = 15000L' in policy and 'CHARON_READ_TIMEOUT_MS = 60000' in policy and 'timeout real da conexão' in main)
check('requisição Charon cancelável', 'SpeechRequest' in (java/'GeminiService.java').read_text('utf-8') and 'activeCharonRequest' in main and 'request.cancel()' in main)
check('cache TTS V7', 'tts-v7' in cache and 'MAX_ENTRIES=72' in cache and 'pt-BR' in cache)
check('blocos progressivos sem fragmentação excessiva', 'CHARON_FIRST_BLOCK' in chunker and 'ANDROID_NEXT_BLOCK' in chunker and 'NarrationChunker.android' in main)
check('cinco canais preservados', all(x in controller for x in ('voiceVol','sfxVol','ambienceVol','climateVol','musicVol')))
check('ducking durante voz', 'effectiveMusicVolume' in controller and 'effectiveAmbienceVolume' in controller and 'effectiveClimateVolume() { return climateVol; }' in controller)
check('ambiência aguarda voz', 'voiceStartedForPreparation' in narrative and 'voice_confirmed_for_scene' in narrative)
check('sincronização por caractere', 'charIndex' in narrative and 'durationMs*(cue.charIndex/(float)length)' in narrative)
check('WorkManager retomável', 'extends Worker' in worker and '.partial' in worker and 'getFD().sync' in worker and 'Result.retry()' in worker)
check('importa pasta e ZIP', 'DocumentFile' in worker and 'ZipInputStream' in worker)
check('copia para interno', 'context.getFilesDir()' in worker and 'Uri.fromFile(target)' in worker)
check('permissões do Worker', all(x in manifest for x in ('FOREGROUND_SERVICE','FOREGROUND_SERVICE_DATA_SYNC','POST_NOTIFICATIONS')))
check('naturalização de hex', 'Pattern.compile' in naturalizer and 'getMapHex' in naturalizer and 'terrainLabel' in naturalizer and 'direction' in naturalizer)
check('naturalização antes de narrar/salvar', 'NarrativeLocationNaturalizer.naturalize' in main)
check('diagnóstico persistente', 'audio_events_v3.jsonl' in diagnostics and 'latencyMs' in diagnostics)
check('banco com WAL', 'setWriteAheadLoggingEnabled(true)' in db and 'PRAGMA busy_timeout=8000' in db)
manual_identity=(java/'ManualIdentityPolicy.java').read_text('utf-8')
check('D&D exclui mystara_', 'ManualIdentityPolicy.isMystaraTitle(title)' in main and 'WORLD_MYSTARA.equals(world)?exactMystara:!exactMystara' in main and 'startsWith("mystara_")' in manual_identity)

check('sessão capturada nos callbacks Charon', 'final AudioSessionCoordinator.Session coordinated=activeAudioSession' in main and 'isCurrentAudioSession(coordinated)' in main and 'event(coordinated,"charon-synthesis-ready"' in main)
check('eventos antigos não entram na sessão nova', 'if (!isCurrent(session)) return;' in session)
check('chave alternativa Charon protegida', 'gemini_paid_key' in main and 'geminiPaidKey()' in main and 'synthesizeSpeech(key,paidKey' in main)
check('circuit breaker TTS de cinco minutos', 'TTS_PRIMARY_CIRCUIT_MS=5L*60L*1000L' in (java/'GeminiService.java').read_text('utf-8') and 'PREF_TTS_PRIMARY_CIRCUIT_UNTIL' in (java/'GeminiService.java').read_text('utf-8'))
check('WorkManager em primeiro plano Android 14', 'setForegroundAsync(foreground(' in worker and '.get()' in worker and 'FOREGROUND_SERVICE_TYPE_DATA_SYNC' in worker and 'SystemForegroundService' in manifest and 'foregroundServiceType="dataSync"' in manifest)
check('monitor de importação retomado ao iniciar', 'resumeAudioImportMonitor();' in main and 'getWorkInfosForUniqueWork' in main and 'audio_import_applied_work_id' in main)
check('checkpoint do mesmo trabalho', 'audio_import_checkpoint_v3.json' in worker and 'jobId.equals(checkpoint.optString("job_id"))' in worker)
check('SoundPool encerra streams antigos', 'activeStreams' in soundpool and 'pool.stop(streamId)' in soundpool and 'activeStreams.clear()' in soundpool)
check('SFX reserva gatilho antes do carregamento', 'pendingSfxKeys.add(key)' in controller and 'pendingSfxKeys.contains(key)' in controller and 'pendingSfxKeys.remove(key)' in controller)
check('fallback de SFX não vaza entre sessões', 'expectedPlaybackGeneration!=playbackGeneration' in controller and 'expectedSessionId.equals(playbackSessionId)' in controller)
check('SoundPool toca e registra sob o mesmo bloqueio', 'playedSession=sessionId' in soundpool and 'final int streamId;final String playedSession;' in soundpool)
check('foco moderno e retirada de fone segura', 'AudioFocusRequest.Builder' in controller and 'abandonAudioFocusRequest' in controller and 'ACTION_AUDIO_BECOMING_NOISY' in controller)
check('ducking do sistema reduz SoundPool', 'setOutputFactor(.20f)' in controller and 'activeStreamVolumes' in soundpool and 'pool.setVolume' in soundpool)
check('volumes canônicos do projeto de referência', 'ambienceVol = .35f' in controller and 'climateVol = .28f' in controller and 'musicVol = .14f' in controller and 'sfxVol = .80f' in controller and 'voiceVol = 1f' in controller)
check('ducking canônico sem reduzir clima', 'ambienceVol * (ducked ? .58f : 1f)' in controller and 'musicVol * (ducked ? .34f : 1f)' in controller and 'effectiveClimateVolume() { return climateVol; }' in controller)
check('naturalizador evita sala/tabela/página', all(x in naturalizer for x in ('sala','tabela','página')))
check('diagnóstico separado por canal', 'testImportedAudioChannel' in main and all(x in main for x in ('TESTAR AMBIÊNCIA','TESTAR CLIMA','TESTAR MÚSICA','TESTAR SFX','TESTAR CHARON','TESTAR VOZ DO ANDROID')))
check('migração preserva biblioteca e campanha', 'audio_core_4_2_migrated' in main and 'Os arquivos de som importados foram preservados' in main and 'deleteAudioTree(new File(getFilesDir(),"audio_library"))' not in main)
check('gravação atômica lógica das chaves Gemini', 'saveGeminiSecretsAtomically' in main and 'rollbackPrimary' in main and 'rollbackPaid' in main)
check('ZIP de áudio possui limites contra expansão', 'MAX_SINGLE_AUDIO_BYTES' in worker and 'MAX_TOTAL_IMPORT_BYTES' in worker and 'visited > MAX_FILES' in worker and 'totalCopiedBytes + copied > MAX_TOTAL_IMPORT_BYTES' in worker)
check('arquivo parcial é removido após falha', 'if (!completed) { cleanup(target); signatures.remove(signature); }' in worker)
java_sources='\n'.join(path.read_text('utf-8') for path in java.glob('*.java'))
check('sem retornos idênticos consecutivos', re.search(r'return\s+([^;\n]+);\n[ \t]*return\s+\1;', java_sources) is None)
failed=[name for name,ok in checks if not ok]
for name,ok in checks: print(('OK  ' if ok else 'FALHA ')+name)
print(f'RESULTADO: {len(checks)-len(failed)}/{len(checks)} verificações aprovadas')
sys.exit(1 if failed else 0)
